import * as React from "react"
import { ArrowDownRight, ArrowUpRight, Minus } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  TREND_TEXT,
  conventionClass,
  formatStat,
  toneColor,
  trendOf,
  type DataConvention,
  type DataTone,
  type StatFormatOptions,
  type Trend,
} from "@/lib/data-display"

import {
  DEFAULT_LABELS,
  healthStatus,
  usageStatus,
  type StatLabels,
  type StatStatusName,
} from "./config"
import {
  StatBadge,
  StatStatus,
  type StatBadgeProps,
  type StatStatusProps,
} from "./stat-status"
import {
  StatDistribution,
  StatMeter,
  StatProgress,
  StatSegments,
  type StatDistributionProps,
  type StatMeterProps,
  type StatProgressProps,
  type StatSegment,
  type StatSegmentsProps,
} from "./stat-bars"
import { StatZones, type StatZone, type StatZonesProps } from "./stat-zones"

type StatCardProps = React.ComponentProps<"div"> & {
  /**
   * 涨跌配色约定：`intl` 绿涨红跌，`cn` 红涨绿跌。
   * 变量沿 DOM 继承，给外层容器设置一次，里面所有卡片与图表都会跟着变；不设置时沿用外层，最外层默认 `intl`
   */
  convention?: DataConvention
}

/** 统计卡片的外壳：细边框、无阴影，内容用下面的原语自由组合。 */
function StatCard({ className, convention, ...props }: StatCardProps) {
  return (
    <div
      data-slot="stat-card"
      data-convention={convention}
      className={cn(
        "flex min-w-0 flex-col gap-3 rounded-lg border border-edge bg-card p-4 text-sm text-card-foreground",
        conventionClass(convention),
        className,
      )}
      {...props}
    />
  )
}

type StatGroupProps = React.ComponentProps<"div"> & {
  /** 这一组里所有卡片、涨跌幅与图表共用的涨跌配色约定 */
  convention?: DataConvention
}

/** 一组卡片的容器：只负责统一设置 `convention`，布局由 `className` 决定。 */
function StatGroup({ className, convention, ...props }: StatGroupProps) {
  return (
    <div
      data-slot="stat-group"
      data-convention={convention}
      className={cn(conventionClass(convention), className)}
      {...props}
    />
  )
}

/** 标题行：左边放 `StatLabel`，右边放图标或状态徽标。 */
function StatHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="stat-header"
      className={cn("flex items-start justify-between gap-3", className)}
      {...props}
    />
  )
}

/** 指标名称，12–13px 的次要文字。 */
function StatLabel({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="stat-label"
      className={cn("min-w-0 truncate text-[13px] leading-5 text-muted-foreground", className)}
      {...props}
    />
  )
}

type StatIconProps = React.ComponentProps<"span"> & {
  /** 图标色调；不设置时为次要文字色 */
  tone?: DataTone
}

/** 图标方块：`size-8` 的细边框小方块，里面放一个 lucide 图标。 */
function StatIcon({ className, tone, style, ...props }: StatIconProps) {
  return (
    <span
      data-slot="stat-icon"
      aria-hidden="true"
      data-tone={tone}
      className={cn(
        "flex size-8 shrink-0 items-center justify-center rounded-md border border-edge bg-muted/50 text-muted-foreground data-[tone]:text-[color:var(--stat-tone)] [&_svg:not([class*='size-'])]:size-4",
        className,
      )}
      style={
        tone
          ? ({
              "--stat-tone": toneColor(tone),
              ...style,
            } as React.CSSProperties)
          : style
      }
      {...props}
    />
  )
}

type StatValueProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** 数值；数字会按 `format` 格式化，字符串原样显示 */
  value?: number | string
  /** 数字格式，默认 `zh-CN` 压缩（1.2万、3.4亿） */
  format?: StatFormatOptions
  /** 单位，跟在数字后，字号更小、颜色更淡 */
  unit?: React.ReactNode
  /**
   * 字号：`sm` 20px、`default` 24px、`lg` 30px
   * @default "default"
   */
  size?: "sm" | "default" | "lg"
  /** 自定义内容，传入后替代 `value` */
  children?: React.ReactNode
}

const VALUE_SIZES = {
  sm: "text-xl",
  default: "text-2xl",
  lg: "text-3xl",
} as const

/** 大号数字加单位；数字一律等宽对齐（`tabular-nums`）。 */
function StatValue({
  className,
  value,
  format,
  unit,
  size = "default",
  children,
  ...props
}: StatValueProps) {
  const text = typeof value === "number" ? formatStat(value, format) : value
  return (
    <div
      data-slot="stat-value"
      data-size={size}
      className={cn(
        "flex items-baseline gap-1.5 leading-none font-semibold tracking-tight tabular-nums",
        VALUE_SIZES[size],
        className,
      )}
      {...props}
    >
      <span data-slot="stat-value-number">{children ?? text}</span>
      {unit ? (
        <span
          data-slot="stat-unit"
          className="text-sm font-normal tracking-normal text-muted-foreground"
        >
          {unit}
        </span>
      ) : null}
    </div>
  )
}

type StatTrendProps = Omit<React.ComponentProps<"span">, "children"> & {
  /** 涨跌幅，单位是百分点：`12.4` 表示 +12.4% */
  value: number
  /** 数字格式，默认带正负号的百分比 */
  format?: StatFormatOptions
  /**
   * 越低越好的指标（延迟、错误率）：下降显示为「好」的颜色，箭头方向不变
   * @default false
   */
  invert?: boolean
  /**
   * 显示方向箭头
   * @default true
   */
  showIcon?: boolean
  /** 单独指定涨跌配色约定，不设置时沿用外层 */
  convention?: DataConvention
  /** 覆盖读屏文字（上升 / 下降 / 持平） */
  labels?: Partial<Pick<StatLabels, "up" | "down" | "flat">>
  /** 数字后的说明，如「较上周」 */
  children?: React.ReactNode
}

const TREND_ICONS = {
  up: ArrowUpRight,
  down: ArrowDownRight,
  flat: Minus,
} as const

const OPPOSITE: Record<Trend, Trend> = { up: "down", down: "up", flat: "flat" }

/** 涨跌幅：箭头 + 带符号的百分比；颜色来自 `convention`，同时有箭头和读屏文字，不只靠颜色。 */
function StatTrend({
  className,
  value,
  format,
  invert = false,
  showIcon = true,
  convention,
  labels,
  children,
  ...props
}: StatTrendProps) {
  const trend = trendOf(value)
  const Icon = TREND_ICONS[trend]
  const text = { ...DEFAULT_LABELS, ...labels }
  return (
    <span
      data-slot="stat-trend"
      data-trend={trend}
      className={cn(
        "inline-flex flex-wrap items-center gap-0.5 whitespace-nowrap text-xs font-medium tabular-nums",
        TREND_TEXT[invert ? OPPOSITE[trend] : trend],
        conventionClass(convention),
        className,
      )}
      {...props}
    >
      {showIcon ? <Icon aria-hidden="true" className="size-3.5 shrink-0" /> : null}
      <span className="sr-only">{text[trend]}</span>
      {formatStat(value, { style: "percent", sign: true, ...format })}
      {children ? (
        <span className="ml-1 font-normal text-muted-foreground">
          {children}
        </span>
      ) : null}
    </span>
  )
}

/** 两端对齐的说明行，放在进度条 / 计量条下面：左边「剩余 62%」，右边「已用 3.8 / 10 GB」。 */
function StatMeta({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="stat-meta"
      className={cn(
        "flex items-center justify-between gap-3 text-xs text-muted-foreground tabular-nums",
        className,
      )}
      {...props}
    />
  )
}

export {
  StatBadge,
  StatCard,
  StatDistribution,
  StatGroup,
  StatHeader,
  StatIcon,
  StatLabel,
  StatMeta,
  StatMeter,
  StatProgress,
  StatSegments,
  StatStatus,
  StatTrend,
  StatValue,
  StatZones,
  healthStatus,
  usageStatus,
}
export type {
  StatBadgeProps,
  StatCardProps,
  StatDistributionProps,
  StatGroupProps,
  StatIconProps,
  StatLabels,
  StatMeterProps,
  StatProgressProps,
  StatSegment,
  StatSegmentsProps,
  StatStatusName,
  StatStatusProps,
  StatTrendProps,
  StatValueProps,
  StatZone,
  StatZonesProps,
}

import * as React from "react"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"
import { ChevronRight } from "lucide-react"

import { cn } from "@/lib/utils"
import { toneColor, type DataTone } from "@/lib/data-display"

import {
  DEFAULT_LABELS,
  STATUS_ICONS,
  STATUS_TONES,
  type StatLabels,
  type StatStatusName,
} from "./config"

// 浅色下多彩色调直接当文字色对比度偏低，向前景色混入一部分压深；暗色下同样的混合会略微提亮，两边都清晰。
const TONE_TEXT =
  "text-[color:color-mix(in_oklab,var(--stat-tone)_72%,var(--foreground))]"

function toneVars(tone: DataTone, style?: React.CSSProperties) {
  return { "--stat-tone": toneColor(tone), ...style } as React.CSSProperties
}

type StatStatusProps = useRender.ComponentProps<"div"> & {
  /** 状态：达标 / 关注 / 风险 / 审核中，决定图标、色调和默认文字 */
  status: StatStatusName
  /** 覆盖状态文字 */
  label?: string
  /** 覆盖四种状态的默认文字 */
  labels?: Partial<StatLabels>
  /**
   * 右侧显示 `>` 箭头，配合 `render` 做成可点击的入口
   * @default false
   */
  showChevron?: boolean
}

/**
 * 状态行：状态图标方块 + 两行文字（上：说明，如「3/5 个目标」；下：状态名）。
 * 想让整行可点击，用 `render={<a href="…" />}` 换成链接。
 */
function StatStatus({
  className,
  status,
  label,
  labels,
  showChevron = false,
  render,
  children,
  style,
  ...props
}: StatStatusProps) {
  const Icon = STATUS_ICONS[status]
  const text = label ?? { ...DEFAULT_LABELS, ...labels }[status]
  return useRender({
    defaultTagName: "div",
    render,
    props: mergeProps<"div">(
      {
        className: cn(
          "flex w-full items-center gap-3 rounded-md bg-muted/50 px-3 py-2 text-left transition-colors outline-none focus-visible:ring-3 focus-visible:ring-ring/50",
          render && "hover:bg-muted",
          className,
        ),
        style: toneVars(STATUS_TONES[status], style),
        children: (
          <>
            <span
              aria-hidden="true"
              className="flex size-8 shrink-0 items-center justify-center rounded-md bg-[color:var(--stat-tone)] text-background [&_svg]:size-4"
            >
              <Icon />
            </span>
            <span className="flex min-w-0 flex-1 flex-col gap-0.5 text-xs leading-4 font-medium">
              <span className="truncate text-foreground">{children}</span>
              <span className={TONE_TEXT}>{text}</span>
            </span>
            {showChevron ? (
              <ChevronRight
                aria-hidden="true"
                className="size-4 shrink-0 text-muted-foreground"
              />
            ) : null}
          </>
        ),
      },
      {
        "data-slot": "stat-status",
        "data-status": status,
        ...props,
      } as React.ComponentProps<"div">,
    ),
  })
}

type StatBadgeProps = React.ComponentProps<"span"> & {
  /** 用状态决定色调与默认文字；与 `tone` 二选一 */
  status?: StatStatusName
  /** 直接指定色调 */
  tone?: DataTone
  /** 覆盖四种状态的默认文字 */
  labels?: Partial<StatLabels>
}

/** 状态徽标：色点 + 文字的小药丸。颜色之外永远有文字，不依赖颜色传达状态。 */
function StatBadge({
  className,
  status,
  tone,
  labels,
  style,
  children,
  ...props
}: StatBadgeProps) {
  const color = tone ?? (status ? STATUS_TONES[status] : "muted")
  return (
    <span
      data-slot="stat-badge"
      data-status={status}
      className={cn(
        "inline-flex h-5 w-fit shrink-0 items-center gap-1.5 rounded-full border border-edge px-2 text-xs font-medium whitespace-nowrap text-foreground",
        className,
      )}
      style={toneVars(color, style)}
      {...props}
    >
      <span
        aria-hidden="true"
        className="size-1.5 rounded-full bg-[color:var(--stat-tone)]"
      />
      {children ?? (status ? { ...DEFAULT_LABELS, ...labels }[status] : null)}
    </span>
  )
}

export { StatBadge, StatStatus }
export type { StatBadgeProps, StatStatusProps }

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  SERIES_TONES,
  formatStat,
  motionStyles,
  toneColor,
  type DataTone,
  type StatFormatOptions,
} from "@/lib/data-display"

import {
  DEFAULT_LABELS,
  STATUS_TONES,
  healthStatus,
  usageStatus,
  type StatLabels,
} from "./config"

function toneVar(tone: DataTone, style?: React.CSSProperties) {
  return { "--stat-tone": toneColor(tone), ...style } as React.CSSProperties
}

const clampPercent = (value: number, max: number) =>
  max > 0 ? Math.min(100, Math.max(0, (value / max) * 100)) : 0

type StatProgressProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** 当前值 */
  value: number
  /**
   * 满值
   * @default 100
   */
  max?: number
  /**
   * 填充色。`"usage"`：按用量自动变色（65% 起关注、90% 起风险），适合配额；
   * `"health"`：按健康度变色（低于 40% 风险、低于 75% 关注）
   * @default "primary"
   */
  tone?: DataTone | "usage" | "health"
  /**
   * 粗细：`sm` 4px、`default` 6px、`lg` 8px
   * @default "default"
   */
  size?: "sm" | "default" | "lg"
  /** 读屏名称 */
  label?: string
  /** 覆盖默认文案 */
  labels?: Partial<StatLabels>
}

const BAR_SIZES = { sm: "h-1", default: "h-1.5", lg: "h-2" } as const

function autoTone(tone: StatProgressProps["tone"], percent: number): DataTone {
  if (tone === "usage") return STATUS_TONES[usageStatus(percent)]
  if (tone === "health") return STATUS_TONES[healthStatus(percent)]
  return tone ?? "primary"
}

/** 进度条：服务端直接输出最终宽度，填充用 CSS 从左向右展开；系统开启「减少动态效果」时不播放。 */
function StatProgress({
  className,
  value,
  max = 100,
  tone,
  size = "default",
  label,
  labels,
  style,
  ...props
}: StatProgressProps) {
  const percent = clampPercent(value, max)
  return (
    <div
      data-slot="stat-progress"
      role="progressbar"
      aria-label={label ?? { ...DEFAULT_LABELS, ...labels }.progress}
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={value}
      className={cn(
        "w-full overflow-hidden rounded-full bg-muted",
        BAR_SIZES[size],
        className,
      )}
      style={toneVar(autoTone(tone, percent), style)}
      {...props}
    >
      {motionStyles()}
      <div
        data-slot="stat-progress-fill"
        data-dd-anim="reveal"
        className="h-full rounded-full bg-[color:var(--stat-tone)]"
        style={{ width: `${percent}%` }}
      />
    </div>
  )
}

type StatMeterProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** 0–100 的百分比，按它点亮格子 */
  value: number
  /**
   * 格数
   * @default 10
   */
  segments?: number
  /**
   * 点亮的颜色。默认按健康度自动变色：低于 40% 风险、低于 75% 关注，其余达标
   * @default "health"
   */
  tone?: DataTone | "health" | "usage"
  /** 读屏名称 */
  label?: string
  /** 覆盖默认文案 */
  labels?: Partial<StatLabels>
}

/** 分格计量条：N 个小格，按值从左到右依次点亮；常用来表示服务健康度。 */
function StatMeter({
  className,
  value,
  segments = 10,
  tone = "health",
  label,
  labels,
  style,
  ...props
}: StatMeterProps) {
  const percent = clampPercent(value, 100)
  const lit = Math.round((percent * segments) / 100)
  return (
    <div
      data-slot="stat-meter"
      role="meter"
      aria-label={label ?? { ...DEFAULT_LABELS, ...labels }.meter}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={value}
      className={cn("flex h-6 w-28 items-stretch gap-0.5", className)}
      style={toneVar(autoTone(tone, percent), style)}
      {...props}
    >
      {motionStyles()}
      {Array.from({ length: segments }, (_, index) =>
        index < lit ? (
          <span
            key={index}
            data-state="on"
            data-dd-anim="rise"
            className="flex-1 origin-bottom rounded-[3px] bg-[color:var(--stat-tone)]"
            style={{ animationDelay: `${index * 40}ms` }}
          />
        ) : (
          <span
            key={index}
            data-state="off"
            className="flex-1 rounded-[3px] bg-foreground/8"
          />
        ),
      )}
    </div>
  )
}

type StatSegment = {
  /** 分类名 */
  label: string
  /** 数值，按占比决定宽度 */
  value: number
  /** 色调，不设置时按顺序取默认色板 */
  tone?: DataTone
}

type StatSegmentsProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** 分段数据 */
  segments: StatSegment[]
  /** 读屏名称；默认把每段的占比念出来 */
  label?: string
}

/** 横向分段条：每段宽度按占比分配，段间留 2px 缝；整条从左向右扫出。 */
function StatSegments({
  className,
  segments,
  label,
  ...props
}: StatSegmentsProps) {
  const total = segments.reduce((sum, item) => sum + item.value, 0)
  const summary =
    label ??
    segments
      .map(
        (item) =>
          `${item.label} ${formatStat(total ? (item.value / total) * 100 : 0, { style: "percent" })}`,
      )
      .join("，")
  return (
    <div
      data-slot="stat-segments"
      role="img"
      aria-label={summary}
      className={cn("h-2 w-full", className)}
      {...props}
    >
      {motionStyles()}
      <div
        data-dd-anim="reveal"
        className="flex size-full gap-0.5 overflow-hidden rounded-full"
      >
        {segments.map((item, index) =>
          item.value > 0 ? (
            <span
              key={item.label}
              className="h-full min-w-0 basis-0"
              style={{
                flexGrow: item.value,
                backgroundColor: toneColor(
                  item.tone ?? SERIES_TONES[index % SERIES_TONES.length],
                ),
              }}
            />
          ) : null,
        )}
      </div>
    </div>
  )
}

type StatDistributionProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** 分段数据 */
  segments: StatSegment[]
  /** 图例里每项数值的格式，默认 `zh-CN` 压缩 */
  format?: StatFormatOptions
  /**
   * 显示图例格（色条 + 分类名 + 占比 + 数值）
   * @default true
   */
  legend?: boolean
  /**
   * 图例列数上限，窄屏自动减少
   * @default 4
   */
  columns?: 2 | 3 | 4
}

const LEGEND_COLUMNS = {
  2: "grid-cols-1 sm:grid-cols-2",
  3: "grid-cols-1 sm:grid-cols-3",
  4: "grid-cols-1 sm:grid-cols-2 lg:grid-cols-4",
} as const

/** 占比分布：分段条加图例格。图例同时写出占比和数值，不靠颜色区分分类。 */
function StatDistribution({
  className,
  segments,
  format,
  legend = true,
  columns = 4,
  ...props
}: StatDistributionProps) {
  const total = segments.reduce((sum, item) => sum + item.value, 0)
  return (
    <div
      data-slot="stat-distribution"
      className={cn("flex flex-col gap-3", className)}
      {...props}
    >
      <StatSegments segments={segments} />
      {legend ? (
        <ul
          data-slot="stat-legend"
          className={cn("grid gap-2", LEGEND_COLUMNS[columns])}
        >
          {segments.map((item, index) => {
            const percent = total ? (item.value / total) * 100 : 0
            return (
              <li
                key={item.label}
                data-slot="stat-legend-item"
                className="flex items-center gap-2.5 rounded-md border border-edge px-3 py-2"
              >
                <span
                  aria-hidden="true"
                  className="h-8 w-1 shrink-0 rounded-full"
                  style={{
                    backgroundColor: toneColor(
                      item.tone ?? SERIES_TONES[index % SERIES_TONES.length],
                    ),
                  }}
                />
                <div className="flex min-w-0 flex-col gap-0.5">
                  <span className="truncate text-xs text-muted-foreground">
                    {item.label}
                  </span>
                  <span className="text-sm font-semibold tabular-nums">
                    {formatStat(percent, { style: "percent" })}
                    <span className="ml-1.5 font-normal text-muted-foreground">
                      {formatStat(item.value, format)}
                    </span>
                  </span>
                </div>
              </li>
            )
          })}
        </ul>
      ) : null}
    </div>
  )
}

export { StatDistribution, StatMeter, StatProgress, StatSegments }
export type {
  StatDistributionProps,
  StatMeterProps,
  StatProgressProps,
  StatSegment,
  StatSegmentsProps,
}

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  formatStat,
  toneColor,
  type DataTone,
} from "@/lib/data-display"

