/** 达标 / 关注 / 风险 / 审核中，四种状态与它们的色调、图标。 */
type StatStatusName = "ok" | "watch" | "risk" | "review"

const STATUS_TONES: Record<StatStatusName, DataTone> = {
  ok: "green",
  watch: "amber",
  risk: "rose",
  review: "blue",
}

const STATUS_ICONS: Record<StatStatusName, LucideIcon> = {
